// Generated by `cargo xtask add-card`.
// Round-trip regression test for the generated test suite.
//
// Card           : Scavenging Ghoul
// Set            : lea
// Collector #    : 126

#[test]
fn round_trip() {
    let text = "At the beginning of each end step, put a corpse counter on this creature for each creature that died this turn.\nRemove a corpse counter from this creature: Regenerate this creature.";
    let ast = mtg_grammar::parse(text).expect("parse");
    let reprinted = mtg_grammar::unparse(&ast);
    assert_eq!(
        reprinted, text,
        "unparse must preserve the normalized oracle text"
    );
    let ast2 = mtg_grammar::parse(&reprinted).expect("reparse");
    assert_eq!(ast, ast2);
}
